mapper.update:
UPDATE coupon
SET issued_qty = issued_qty + 1,
    updated_at = NOW()
WHERE coupon_id = #{couponId}
  AND status = 'ACTIVE'
  AND issued_qty < total_qty
  AND start_at <= #{now}
  AND end_at >= #{now}
  AND is_deleted = 0
